<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">include(</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">&#39;sub-project-b&#39;</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">)</span></span>
